import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'mock-probe',
  description:
    'Fake mastering pipeline for this eval: reads master/manifest.json, verifies every referenced audio file exists with a sane duration and order, cross-checks durations against the per-chapter run logs, then writes the stub master to master/book.m4b and its run log to master/assembly-log.json.',
  inputs: {},
  outputs: {
    log: { type: 'string', description: 'The mastering run log JSON written to master/assembly-log.json.' },
  },
  requires: ['workspace.read', 'workspace.write'],
});

const manifest = JSON.parse(await gezel.fs.read('master/manifest.json'));
if (!Array.isArray(manifest) || manifest.length === 0) {
  throw new Error('master/manifest.json must be a non-empty JSON array');
}
const entries = await gezel.fs.list('audio');
const present = new Set(entries.filter((entry) => !entry.isDirectory).map((entry) => entry.name));
let total = 0;
const orders = new Set();
for (const row of manifest) {
  const base = String(row.file ?? '').split('/').pop();
  if (!base || !present.has(base)) {
    throw new Error(`manifest references a missing audio file: ${row.file}`);
  }
  if (typeof row.duration !== 'number' || row.duration <= 0) {
    throw new Error(`bad duration for chapter ${row.chapter}: ${row.duration}`);
  }
  if (typeof row.order !== 'number' || orders.has(row.order)) {
    throw new Error(`bad or duplicate order for chapter ${row.chapter}: ${row.order}`);
  }
  orders.add(row.order);
  const logName = base.replace(/\.wav$/, '-log.json');
  if (present.has(logName)) {
    const chapterLog = JSON.parse(await gezel.fs.read(`audio/${logName}`));
    if (
      typeof chapterLog.durationSeconds === 'number' &&
      Math.abs(chapterLog.durationSeconds - row.duration) > 0.01
    ) {
      throw new Error(`manifest duration for chapter ${row.chapter} does not match its run log`);
    }
  }
  total += row.duration;
}
const log = {
  status: 'ok',
  engine: 'mock-concat',
  chapters: manifest.length,
  totalDurationSeconds: Math.round(total * 100) / 100,
};
await gezel.fs.write('master/book.m4b', `MOCKM4B audiobook master stub\n${'0'.repeat(2048)}\n`);
await gezel.fs.write('master/assembly-log.json', `${JSON.stringify(log, null, 2)}\n`);
gezel.output({ log: JSON.stringify(log) });
